// ---- Parse Command (step 2) ----
// Reads the Telegram message, extracts the command and the free text,
// checks the strict /done format, and prepares the help text.

const msg = $input.first().json.message || {};
const raw = (msg.text || '').trim();
const chat_id = msg.chat?.id;
const sender = msg.from?.first_name || '';

// Escape text before putting it in a Telegram HTML message
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const USAGE = [
  '<b>BetterRhythm commands</b>',
  '',
  '/plan: plan your day',
  '<code>/plan finish report, dentist 15:00, gym, slept badly</code>',
  '',
  '/replan: change today\'s plan',
  '<code>/replan dentist moved to 17:00</code>',
  '',
  '/done: tell me how the day went',
  '<code>/done report 9-12, gym skipped</code>',
  '',
  '/help: show this list',
].join('\n');

// "/plan@MyBot some text" -> cmd = "plan", text = "some text"
const m = raw.match(/^\/(\w+)(?:@\w+)?\s*([\s\S]*)$/);
let cmd = m ? m[1].toLowerCase() : 'unknown';
const text = m ? m[2].trim() : raw;

let reply = '';
let done_items = [];

if (!['plan', 'replan', 'done', 'help'].includes(cmd)) {
  // Unknown command or plain text -> show help
  cmd = 'help';
  reply = (raw ? "I didn't recognise that.\n\n" : '') + USAGE;

} else if (cmd === 'help') {
  reply = USAGE;

} else if (!text) {
  // /plan, /replan or /done with nothing after it
  reply = `Please add some details after /${cmd}.\n\n` + USAGE;
  cmd = 'help';

} else if (cmd === 'done') {
  // Strict format: "task 9-12, task 14:30-16, task skipped"
  const range = /^(.+?)\s+(\d{1,2})(?::(\d{2}))?\s*-\s*(\d{1,2})(?::(\d{2}))?$/;
  const bad = [];

  for (const part of text.split(',').map(p => p.trim()).filter(Boolean)) {
    const skip = part.match(/^(.+?)\s+skipped$/i);
    const r = part.match(range);

    if (skip) {
      done_items.push({ task: skip[1].trim().toLowerCase(), status: 'skipped' });
    } else if (r) {
      const start = Number(r[2]) * 60 + Number(r[3] || 0); // minutes since midnight
      const end = Number(r[4]) * 60 + Number(r[5] || 0);
      if (Number(r[2]) > 23 || Number(r[4]) > 23 || end <= start) {
        bad.push(part);
      } else {
        done_items.push({ task: r[1].trim().toLowerCase(), status: 'done', start, end });
      }
    } else {
      bad.push(part);
    }
  }

  if (bad.length) {
    reply = `I couldn't read: <i>${esc(bad.join(', '))}</i>\n\n` +
            'Use this format:\n<code>/done report 9-12, emails 14:30-15, gym skipped</code>';
    cmd = 'help';
    done_items = [];
  }
}

return [{ json: { cmd, text, chat_id, sender, reply, done_items } }];

// ---- Update Profile (step 4a) ----
// Compares what was planned today with what really happened,
// then updates the time factor and the peak hours.

const parsed = $('Parse Command').first().json;
const profile = $('Load Profile').first().json;
const items = parsed.done_items || [];
const planned = [...(profile.today_planned || [])].reverse(); // newest plan first (after /replan)
const history = profile.history || [];

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const hhmm = (m) => `${String(Math.floor(m / 60)).padStart(2, '0')}:${String(m % 60).padStart(2, '0')}`;

// Match "report" with the planned task (exact name first, then partial)
const used = new Set();
const findPlanned = (name) => {
  let p = planned.find(t => !used.has(t.row_number) && t.task === name);
  if (!p) p = planned.find(t => !used.has(t.row_number) && (t.task.includes(name) || name.includes(t.task)));
  if (p) used.add(p.row_number);
  return p;
};

const task_updates = [];  // rows to update in the tasks tab
const unmatched = [];     // reported tasks that were not in the plan
const todayDone = [];     // done tasks used for learning
let skipped = 0;

for (const it of items) {
  const p = findPlanned(it.task);
  if (!p) { unmatched.push(it.task); continue; }

  if (it.status === 'skipped') {
    skipped++;
    task_updates.push({ row_number: p.row_number, status: 'skipped' });
  } else {
    const actual_min = it.end - it.start;
    task_updates.push({
      row_number: p.row_number,
      actual_start: hhmm(it.start),
      actual_end: hhmm(it.end),
      actual_min,
      status: 'done',
    });
    if (p.planned_min) todayDone.push({ ...p, actual_start: it.start, actual_end: it.end, actual_min });
  }
}

// 1) Time factor: how much longer than estimated tasks really take.
//    Smoothed so one bad day doesn't swing it too much.
const oldTf = profile.time_factor;
let newTf = oldTf;
let ratio = null;
if (todayDone.length) {
  const sumPlanned = todayDone.reduce((s, t) => s + t.planned_min, 0);
  const sumActual = todayDone.reduce((s, t) => s + t.actual_min, 0);
  ratio = sumActual / sumPlanned;
  newTf = Math.min(3, Math.max(0.5, 0.7 * oldTf + 0.3 * ratio));
  newTf = Math.round(newTf * 100) / 100;
}

// 2) Peak hours: the 3-hour window where deep work goes most to plan
//    (efficiency = planned / actual, higher is better; needs 2+ tasks).
const deep = [...history, ...todayDone].filter(t =>
  t.category === 'deep' && t.actual_start != null && t.planned_min && t.actual_min);

let peak_start = profile.peak_start;
let peak_end = profile.peak_end;
let best = null;
const startHours = [...new Set(deep.map(t => Math.floor(t.actual_start / 60)))];

for (const h of startHours) {
  const inWindow = deep.filter(t => {
    const sh = Math.floor(t.actual_start / 60);
    return sh >= h && sh < h + 3;
  });
  if (inWindow.length < 2) continue;
  const eff = inWindow.reduce((s, t) => s + t.planned_min / t.actual_min, 0) / inWindow.length;
  if (!best || eff > best.eff) best = { h, eff };
}
if (best) { peak_start = best.h; peak_end = best.h + 3; }
const peakChanged = peak_start !== profile.peak_start || peak_end !== profile.peak_end;

// 3) Reply message
const lines = ['<b>Day logged</b>', ''];
if (ratio !== null) {
  const pct = Math.round(Math.abs(ratio - 1) * 100);
  lines.push(pct === 0
    ? 'Today your estimates were spot on.'
    : `Today tasks took ${pct}% ${ratio > 1 ? 'longer' : 'less time'} than estimated.`);
  lines.push(`Time factor: ${oldTf} → <b>${newTf}</b>`);
}
lines.push(`Peak focus hours: <b>${peak_start}:00–${peak_end}:00</b> ${peakChanged ? '(updated)' : '(unchanged)'}`);
if (skipped) lines.push(`Skipped: ${skipped} task${skipped > 1 ? 's' : ''}`);
if (unmatched.length) lines.push(`Not in today's plan, so not used for learning: <i>${esc(unmatched.join(', '))}</i>`);
if (ratio === null && !skipped) lines.push("I couldn't match anything to today's plan. Did you send /plan today?");

return [{
  json: {
    reply: lines.join('\n'),
    profile_row: {
      row_number: 2,
      peak_hours: `${peak_start}-${peak_end}`,
      time_factor: newTf,
      recent_energy: profile.recent_energy,
      last_plan_json: profile.last_plan ? JSON.stringify(profile.last_plan) : '',
      updated_at: $now.toISO(),
    },
    signal_row: {
      date: profile.today,
      cmd: 'done',
      energy: profile.recent_energy,
      raw_text: parsed.text,
      weather_ok: '',
    },
    task_updates,
  },
}];

