// ---- Build Schedule (step 8) ----
// Places fixed events (typed + Google Calendar), then deep work in peak hours,
// outdoor tasks in dry hours and light tasks in the gaps. Durations use the
// learned time factor and today's energy. Respects forbidden hours.
// Flags conflicts and drops what does not fit.

const v = $('Validate').first().json;
const profile = $('Load Profile').first().json;
const cmd = $('Parse Command').first().json.cmd;

let weather = null;
try { weather = $('Fetch Weather').first().json; } catch (e) { weather = null; }

const STEP = 15; // minutes
const toMin = (t) => {
  const m = String(t ?? '').match(/^(\d{1,2}):(\d{2})$/);
  return m ? Number(m[1]) * 60 + Number(m[2]) : null;
};
const hhmm = (m) => `${String(Math.floor(m / 60)).padStart(2, '0')}:${String(m % 60).padStart(2, '0')}`;
const roundUp = (m) => Math.ceil(m / STEP) * STEP;

const now = $now;
const todayStr = now.toFormat('yyyy-MM-dd');
const tomorrowStr = now.plus({ days: 1 }).toFormat('yyyy-MM-dd');
const nowMin = now.hour * 60 + now.minute;

// ---------- 1) Inputs (merged with the last plan for /replan) ----------
let tasks = v.tasks || [];
let fixed = v.fixed_events || [];
let energy = v.energy || 'normal';
let dayStartC = v.day_start;
let dayEndC = v.day_end;
let targetDate;

const last = profile.last_plan;

if (cmd === 'replan' && last && last.date >= todayStr) {
  const sameName = (a, b) => a.includes(b) || b.includes(a);
  // New fixed events replace old ones with the same name
  fixed = [
    ...(last.fixed_events || []).filter(e => !fixed.some(n => sameName(n.name, e.name))),
    ...fixed,
  ];
  // Keep the old tasks, add new ones, and don't keep a task that became a fixed event
  tasks = [
    ...(last.tasks || []).filter(t => !fixed.some(e => sameName(e.name, t.name))),
    ...tasks.filter(t => !(last.tasks || []).some(o => sameName(o.name, t.name))),
  ];
  if (energy === 'normal' && last.energy) energy = last.energy;
  dayStartC = dayStartC || last.day_start || '';
  dayEndC = dayEndC || last.day_end || '';
  targetDate = last.date;
} else {
  targetDate = now.hour >= 17 ? tomorrowStr : todayStr;
}

const isToday = targetDate === todayStr;
const dateLabel = isToday ? 'today' : (targetDate === tomorrowStr ? 'tomorrow' : targetDate);

// ---------- 1b) Google Calendar events for the planned day ----------
let calendar = null;
try { calendar = $('Fetch Calendar').first().json; } catch (e) { calendar = null; }
const calendar_ok = Array.isArray(calendar?.items);
const sameText = (a, b) => {
  a = String(a).toLowerCase();
  b = String(b).toLowerCase();
  return a.includes(b) || b.includes(a);
};
const calendarEvents = [];
for (const ev of (calendar?.items || [])) {
  if (ev.status === 'cancelled') continue;
  const sIso = ev.start?.dateTime;
  const eIso = ev.end?.dateTime;
  if (!sIso || !eIso) continue; // all-day events are not time blocks
  const st = DateTime.fromISO(sIso).setZone('Europe/Paris');
  const en = DateTime.fromISO(eIso).setZone('Europe/Paris');
  if (st.toFormat('yyyy-MM-dd') !== targetDate) continue;
  let startMin = st.hour * 60 + st.minute;
  const endMin = en.toFormat('yyyy-MM-dd') === targetDate ? en.hour * 60 + en.minute : 24 * 60;
  if (isToday && endMin <= nowMin) continue;                     // already over
  if (isToday && startMin < nowMin) startMin = roundUp(nowMin);  // already started
  const name = String(ev.summary || 'busy').trim();
  const start = hhmm(startMin);
  // Skip it if the user also typed the same event in their message
  if (fixed.some(f => f.start === start || sameText(f.name, name))) continue;
  calendarEvents.push({ name, start, minutes: Math.max(STEP, endMin - startMin), source: 'calendar' });
}
fixed = [...fixed, ...calendarEvents];

let dayStart = roundUp(toMin(dayStartC) ?? 8 * 60);
if (isToday) dayStart = Math.max(dayStart, roundUp(nowMin));
const dayEnd = toMin(dayEndC) ?? 22 * 60;

// ---------- 2) Durations ----------
const tf = profile.time_factor || 1;
const energyFactor = { low: 1.15, normal: 1, high: 0.95 }[energy] ?? 1;
const blockLen = (base) => Math.max(STEP, roundUp(base * tf * energyFactor));
const breakAfterDeep = energy === 'low' ? 30 : 15;
const peak = [profile.peak_start * 60, profile.peak_end * 60];

// ---------- 3) Weather: rain probability per hour of the target day ----------
const RAIN = 50; // % from which an hour counts as rainy
const rain = {};
const times = weather?.hourly?.time;
const probs = weather?.hourly?.precipitation_probability;
if (Array.isArray(times) && Array.isArray(probs)) {
  times.forEach((t, i) => {
    if (String(t).startsWith(targetDate) && probs[i] !== null) rain[Number(String(t).slice(11, 13))] = probs[i];
  });
}
const weather_ok = Object.keys(rain).length > 0;
const isWet = (start, len) => {
  for (let h = Math.floor(start / 60); h * 60 < start + len; h++) {
    if ((rain[h] ?? 0) >= RAIN) return true;
  }
  return false;
};

// ---------- 4) Fixed events first ----------
const busy = [];      // blocked intervals, in minutes
const schedule = [];  // what the user will see
const conflicts = [];
const overlaps = (a, b) => a.start < b.end && b.start < a.end;
const isFree = (s, e) => s >= dayStart && e <= dayEnd && !busy.some(b => overlaps({ start: s, end: e }, b));

// Forbidden hours from the profile (e.g. lunch): no task gets placed there
for (const b of profile.blocked || []) busy.push({ start: b.start, end: b.end, name: 'blocked' });

const sortedFixed = [...fixed].sort((a, b) => toMin(a.start) - toMin(b.start));
for (const ev of sortedFixed) {
  const s = toMin(ev.start);
  const e = s + ev.minutes;
  if (isToday && s < nowMin) {
    conflicts.push(`${ev.name} at ${ev.start} is already past`);
    continue;
  }
  const clash = schedule.find(b => overlaps({ start: s, end: e }, b));
  if (clash) conflicts.push(`${ev.name} (${ev.start}) overlaps ${clash.name} (${hhmm(clash.start)})`);
  if (s < dayStart || e > dayEnd) conflicts.push(`${ev.name} (${ev.start}) is outside your day (${hhmm(dayStart)}–${hhmm(dayEnd)})`);
  busy.push({ start: s - 15, end: e + 15, name: ev.name }); // 15 min travel buffer
  schedule.push({ start: s, end: e, name: ev.name, kind: 'fixed', note: ev.source === 'calendar' ? 'from your calendar' : '' });
}

// ---------- 5) Find the first free slot matching the preferences ----------
const findSlot = (len, { within = null, avoid = null, dry = false } = {}) => {
  for (let s = dayStart; s + len <= dayEnd; s += STEP) {
    if (!isFree(s, s + len)) continue;
    if (within && (s < within[0] || s >= within[1])) continue;
    if (avoid && s < avoid[1] && s + len > avoid[0]) continue;
    if (dry && isWet(s, len)) continue;
    return s;
  }
  return null;
};

// ---------- 6) Place tasks: deep, then outdoor, then light ----------
const order = { deep: 0, outdoor: 1, light: 2 };
const sortedTasks = [...tasks].sort((a, b) => order[a.category] - order[b.category] || b.minutes - a.minutes);
const dropped = [];

for (const t of sortedTasks) {
  const len = blockLen(t.minutes);
  let s = null;
  let note = '';

  if (t.category === 'deep') {
    // 1) start inside peak hours, 2) otherwise the slot overlapping peak hours most, 3) otherwise anywhere
    s = findSlot(len, { within: peak });
    if (s === null) {
      let bestOverlap = 0;
      for (let c = dayStart; c + len <= dayEnd; c += STEP) {
        if (!isFree(c, c + len)) continue;
        const ov = Math.min(c + len, peak[1]) - Math.max(c, peak[0]);
        if (ov > bestOverlap) { bestOverlap = ov; s = c; }
      }
    }
    if (s === null) s = findSlot(len);
    if (s !== null) {
      const overlap = Math.max(0, Math.min(s + len, peak[1]) - Math.max(s, peak[0]));
      if (overlap === 0) {
        note = isToday && dayStart > peak[0] ? 'peak hours already over today' : 'peak hours were full';
      } else if (s < peak[0] || s + len > peak[1]) {
        note = 'longer than your peak hours';
      }
    }
  } else if (t.category === 'outdoor') {
    if (weather_ok) {
      s = findSlot(len, { dry: true, avoid: peak }) ?? findSlot(len, { dry: true });
      if (s === null) {
        s = findSlot(len, { avoid: peak }) ?? findSlot(len);
        if (s !== null) note = 'rain expected';
      }
    } else {
      s = findSlot(len, { avoid: peak }) ?? findSlot(len);
    }
  } else {
    s = findSlot(len, { avoid: peak }) ?? findSlot(len);
  }

  if (s === null) {
    dropped.push({ name: t.name, minutes: len, reason: 'no free slot long enough' });
    continue;
  }
  const buffer = t.category === 'deep' ? breakAfterDeep : 0;
  busy.push({ start: s, end: s + len + buffer, name: t.name });
  schedule.push({ start: s, end: s + len, name: t.name, kind: t.category, base_minutes: t.minutes, note });
}

schedule.sort((a, b) => a.start - b.start);

// ---------- 7) Output ----------
const rainy_hours = Object.entries(rain)
  .filter(([h, p]) => p >= RAIN && Number(h) * 60 >= dayStart && Number(h) * 60 < dayEnd)
  .map(([h]) => Number(h));

return [{
  json: {
    cmd,
    date: targetDate,
    date_label: dateLabel,
    day_window: `${hhmm(dayStart)}–${hhmm(dayEnd)}`,
    energy,
    time_factor: tf,
    peak_hours: `${profile.peak_start}:00–${profile.peak_end}:00`,
    weather_ok,
    rainy_hours,
    calendar_ok,
    calendar_events: calendarEvents.length,
    schedule: schedule.map(b => ({
      start: hhmm(b.start),
      end: hhmm(b.end),
      name: b.name,
      kind: b.kind,
      note: b.note,
    })),
    dropped,
    conflict: conflicts.length > 0,
    conflicts,
    other_days: v.other_days || [],
    // rows for the tasks tab (fixed events are not saved: nothing to learn from them)
    task_rows: schedule.filter(b => b.kind !== 'fixed').map(b => ({
      date: targetDate,
      task: b.name,
      category: b.kind,
      planned_start: hhmm(b.start),
      planned_end: hhmm(b.end),
      planned_min: b.base_minutes,
      actual_start: '',
      actual_end: '',
      actual_min: '',
      status: 'planned',
    })),
    // saved in the profile so /replan can rebuild from it
    // (calendar events are not saved: they are re-read fresh from Google each time)
    last_plan: {
      date: targetDate,
      tasks,
      fixed_events: fixed.filter(f => f.source !== 'calendar'),
      energy,
      day_start: dayStartC,
      day_end: dayEndC,
    },
  },
}];

