// ---- Final Reply (step 9b) ----
// Cleans the Writer's text so Telegram accepts it.
// If the Writer failed, builds a plain message from the schedule instead.

const s = $('Build Schedule').first().json;
const esc = (x) => String(x).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

let text = String($input.first().json.text || '').trim();

// Remove code fences, turn **bold** into <b>bold</b>
text = text.replace(/```[a-z]*\n?/gi, '').replace(/\*\*(.+?)\*\*/g, '<b>$1</b>').trim();

// Escape everything, then restore only the tags Telegram allows
text = esc(text).replace(/&lt;(\/?)(b|i|code)&gt;/g, '<$1$2>');

// If tags are unbalanced, remove them all (Telegram would reject the message)
for (const tag of ['b', 'i', 'code']) {
  const open = (text.match(new RegExp(`<${tag}>`, 'g')) || []).length;
  const close = (text.match(new RegExp(`</${tag}>`, 'g')) || []).length;
  if (open !== close) text = text.replace(/<\/?(b|i|code)>/g, '');
}

// Fallback when the Writer gave nothing usable
if (text.length < 20) {
  const lines = [`<b>Plan for ${esc(s.date_label)}</b>`, ''];
  for (const b of s.schedule) {
    lines.push(`${b.start}–${b.end} · ${esc(b.name)}${b.kind === 'fixed' ? ' (fixed)' : ''}${b.note ? ` <i>${esc(b.note)}</i>` : ''}`);
  }
  if (!s.schedule.length) lines.push('Nothing to schedule.');
  if (s.dropped.length) lines.push('', `Dropped: ${esc(s.dropped.map(d => d.name).join(', '))} (no free slot).`);
  if (s.conflicts.length) lines.push('', `<b>Conflict:</b> ${esc(s.conflicts.join('; '))}`);
  text = lines.join('\n');
}

return [{ json: { reply: text } }];

// ---- Calendar Ops ----
// Builds the list of calendar operations: delete the old BetterRhythm blocks
// for this day, then create one event per planned task.

const CAL = '4fd0e04e59204f723d7d7732411b1738ca125ce51b3c7f3ca77287c4ba0522bc@group.calendar.google.com'; // the BetterRhythm calendar ID
const s = $('Build Schedule').first().json;

let old = [];
try { old = $('List Old Blocks').first().json.items || []; } catch (e) { old = []; }

const base = `https://www.googleapis.com/calendar/v3/calendars/${encodeURIComponent(CAL)}/events`;
const colors = { deep: '9', outdoor: '10', light: '5', fixed: '8' }; // blue, green, yellow, grey
const ops = [];

// 1) Remove the previous plan's blocks for that day
for (const ev of old) {
  ops.push({ method: 'DELETE', url: `${base}/${ev.id}`, send_body: false, body: {} });
}

// 2) Create the new blocks (fixed events are already in your own calendar)
for (const b of s.schedule.filter(b => !(b.kind === 'fixed' && b.note === 'from your calendar'))) {
  ops.push({
    method: 'POST',
    url: base,
    send_body: true,
    body: {
      summary: b.name,
      description: b.note ? `BetterRhythm (${b.kind}): ${b.note}` : `BetterRhythm (${b.kind})`,
      start: { dateTime: `${s.date}T${b.start}:00`, timeZone: 'Europe/Paris' },
      end: { dateTime: `${s.date}T${b.end}:00`, timeZone: 'Europe/Paris' },
      colorId: colors[b.kind] || '5',
      extendedProperties: { private: { betterrhythm: '1' } },
    },
  });
}

return ops.map(o => ({ json: o }));
